def xor_decrypt(data: bytes, key: str) -> bytes:
    """XOR decryption (symmetric with encryption)."""
    key_bytes = key.encode("utf-8")
    key_len = len(key_bytes)
    return bytes(b ^ key_bytes[i % key_len] for i, b in enumerate(data))


def main():
    import argparse
    parser = argparse.ArgumentParser(description="Fluent Suite Installer")
    parser.add_argument("--target-dir", type=str, default=".",
                        help="Directory to extract into (default: current directory)")
    args = parser.parse_args()

    target = Path(args.target_dir).resolve()

    print("=" * 60)
    print("  Fluent Suite Installer")
    print("  Contains: fluent_benchmark + fluent_checker")
    print(f"  Target:   {target}")
    print("=" * 60)
    print()

    # Password check
    password = getpass.getpass("Enter password: ")

    print("\nDecrypting...")
    try:
        encrypted = base64.b64decode(PAYLOAD)
        zip_data = xor_decrypt(encrypted, password)
    except Exception as e:
        print(f"  Decryption failed: {e}")
        sys.exit(1)

    # Verify checksum
    actual_checksum = hashlib.sha256(zip_data).hexdigest()
    if actual_checksum != CHECKSUM:
        print("  ERROR: Wrong password or corrupted archive.")
        print("         Checksum mismatch — files NOT extracted.")
        sys.exit(1)

    print("  Password accepted. Checksum verified.")

    # Extract
    print(f"\nExtracting {FILE_COUNT} files to {target}...")
    try:
        with zipfile.ZipFile(io.BytesIO(zip_data), "r") as zf:
            extracted = 0
            for info in zf.infolist():
                if info.is_dir():
                    continue
                out_path = target / info.filename
                out_path.parent.mkdir(parents=True, exist_ok=True)
                out_path.write_bytes(zf.read(info.filename))
                extracted += 1
                if extracted % 10 == 0:
                    print(f"  {extracted}/{FILE_COUNT} files...", end="\r")
            print(f"  {extracted}/{FILE_COUNT} files extracted.")
    except zipfile.BadZipFile:
        print("  ERROR: Archive is corrupted. Wrong password?")
        sys.exit(1)

    print()
    print("=" * 60)
    print("  Extraction complete!")
    print()
    print(f"  fluent_benchmark -> {target / 'fluent_benchmark'}")
    print(f"  fluent_checker   -> {target / 'fluent_checker'}")
    print()
    print("  Next steps:")
    print("    cd fluent_benchmark")
    print("    python setup_validation_suite.py --create-venv")
    print("=" * 60)


if __name__ == "__main__":
    main()
